-- ============================================================================
-- 062_arith_simple_interest.sql
-- Question-bank seed: Arithmetic chapter "Simple Interest" -- 37 single-answer MCQs
-- from ACTUAL previous-year papers (bank PO/Clerk, SSC, ICET, IT placement) via
-- IndiaBix, PrepInsta, Testbook, Adda247, Oliveboard, CareerPower, Examveda, 2IIM,
-- GeeksforGeeks, Sawaal. Exam-grade floor; answers independently recomputed & each
-- correct option verified; 4 distinct-valued options, one correct; each carries a
-- worked explanation. Depends on 023. Reuses idempotent _seed_arith_q. Safe to re-run.
-- SI=PRT/100, find rate/time/principal, doubling/tripling, two-part sums, rate change.
-- ============================================================================

create or replace function public._seed_arith_q(p_chapter text, p_difficulty text, p_stem text, p_opts text[], p_correct int, p_explanation text) returns void language plpgsql as $$
declare v_subj uuid; v_chap uuid; v_qid uuid; i int;
begin
  select id into v_subj from public.subject where lower(name)='arithmetic' limit 1;
  if v_subj is null then raise exception 'Arithmetic subject not found (run 023 first)'; end if;
  select id into v_chap from public.chapter where subject_id=v_subj and lower(name)=lower(p_chapter) limit 1;
  if v_chap is null then raise exception 'Chapter % not found', p_chapter; end if;
  if exists (select 1 from public.question where chapter_id=v_chap and stem=p_stem) then return; end if;
  insert into public.question (subject_id, chapter_id, kind, difficulty, answer_type, stem, explanation)
  values (v_subj, v_chap, 'standard', p_difficulty, 'single', p_stem, p_explanation) returning id into v_qid;
  for i in 1..array_length(p_opts,1) loop
    insert into public.question_option (question_id, label, is_correct, position) values (v_qid, p_opts[i], i=p_correct, i-1);
  end loop;
end; $$;

-- Simple Interest (37 questions)
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$Find the simple interest on Rs. 8,000 at 6% per annum for 3 years.$q$,array[$q$Rs. 1,440$q$,$q$Rs. 1,240$q$,$q$Rs. 1,680$q$,$q$Rs. 1,320$q$],1,$q$SI = 8000×6×3/100 = Rs. 1,440.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$What amount will Rs. 12,500 become at 8% per annum simple interest in 4 years?$q$,array[$q$Rs. 15,900$q$,$q$Rs. 16,500$q$,$q$Rs. 17,000$q$,$q$Rs. 16,000$q$],2,$q$SI = 12500×8×4/100 = 4000; Amount = 12500+4000 = Rs. 16,500.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$At what rate percent per annum will Rs. 9,000 yield Rs. 2,160 as simple interest in 4 years?$q$,array[$q$5%$q$,$q$6%$q$,$q$7%$q$,$q$8%$q$],2,$q$R = 2160×100/(9000×4) = 6%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$In how many years will Rs. 7,500 amount to a simple interest of Rs. 3,150 at 6% per annum?$q$,array[$q$6 years$q$,$q$6.5 years$q$,$q$7 years$q$,$q$8 years$q$],3,$q$T = 3150×100/(7500×6) = 7 years.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$A sum earns Rs. 4,800 as simple interest at 8% per annum in 5 years. Find the sum.$q$,array[$q$Rs. 10,000$q$,$q$Rs. 11,000$q$,$q$Rs. 12,000$q$,$q$Rs. 15,000$q$],3,$q$P = 4800×100/(8×5) = Rs. 12,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$Find the simple interest on Rs. 15,000 at 9% per annum for 2 years 6 months.$q$,array[$q$Rs. 3,375$q$,$q$Rs. 3,150$q$,$q$Rs. 2,700$q$,$q$Rs. 3,600$q$],1,$q$T = 2.5 yr; SI = 15000×9×2.5/100 = Rs. 3,375.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$What amount will Rs. 6,400 become at 7.5% per annum simple interest in 2 years?$q$,array[$q$Rs. 7,120$q$,$q$Rs. 7,360$q$,$q$Rs. 7,040$q$,$q$Rs. 7,680$q$],2,$q$SI = 6400×7.5×2/100 = 960; Amount = 6400+960 = Rs. 7,360.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$A sum of Rs. 9,500 amounts to Rs. 11,400 in 2 years at simple interest. Find the rate percent per annum.$q$,array[$q$8%$q$,$q$9%$q$,$q$10%$q$,$q$12%$q$],3,$q$SI = 11400−9500 = 1900; R = 1900×100/(9500×2) = 10%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'easy',$q$Find the simple interest on Rs. 24,000 at 5% per annum for 146 days (take year = 365 days).$q$,array[$q$Rs. 400$q$,$q$Rs. 480$q$,$q$Rs. 520$q$,$q$Rs. 600$q$],2,$q$T = 146/365 = 0.4 yr; SI = 24000×5×0.4/100 = Rs. 480.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$A sum of money doubles itself in 8 years at simple interest. What is the rate percent per annum?$q$,array[$q$10%$q$,$q$12%$q$,$q$12.5%$q$,$q$15%$q$],3,$q$SI = P in 8 yr → R = 100/8 = 12.5%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$A sum becomes three times itself in 20 years at simple interest. Find the rate percent per annum.$q$,array[$q$8%$q$,$q$10%$q$,$q$12%$q$,$q$15%$q$],2,$q$SI = 2P in 20 yr → R = 200/20 = 10%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$At what rate percent per annum will a sum double itself in 12.5 years at simple interest?$q$,array[$q$6%$q$,$q$7.5%$q$,$q$8%$q$,$q$9%$q$],3,$q$R = 100/12.5 = 8%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$A sum of money becomes 2.5 times itself in 10 years at simple interest. Find the rate percent per annum.$q$,array[$q$12%$q$,$q$15%$q$,$q$18%$q$,$q$20%$q$],2,$q$SI = 1.5P in 10 yr → R = 150/10 = 15%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$In how many years will a sum double itself at 8% per annum simple interest?$q$,array[$q$10 years$q$,$q$11 years$q$,$q$12.5 years$q$,$q$14 years$q$],3,$q$T = 100/8 = 12.5 years.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$In how many years will a sum triple itself at 12.5% per annum simple interest?$q$,array[$q$14 years$q$,$q$16 years$q$,$q$18 years$q$,$q$20 years$q$],2,$q$SI = 2P → T = 200/12.5 = 16 years.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$Find the simple interest on Rs. 20,000 at 9% per annum for 2 years 4 months.$q$,array[$q$Rs. 3,900$q$,$q$Rs. 4,200$q$,$q$Rs. 4,500$q$,$q$Rs. 4,050$q$],2,$q$T = 28/12 yr; SI = 20000×9×(28/12)/100 = Rs. 4,200.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$What amount will Rs. 15,000 become at 10% per annum simple interest in 3 years 6 months?$q$,array[$q$Rs. 19,500$q$,$q$Rs. 20,250$q$,$q$Rs. 21,000$q$,$q$Rs. 20,500$q$],2,$q$SI = 15000×10×3.5/100 = 5250; Amount = 15000+5250 = Rs. 20,250.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'medium',$q$A sum of money doubles itself in 10 years at simple interest. In how many years will it triple itself at the same rate?$q$,array[$q$15 years$q$,$q$18 years$q$,$q$20 years$q$,$q$25 years$q$],3,$q$Doubles in 10 yr → R = 10%. To triple, SI = 2P → T = 200/10 = 20 years.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A sum of money at simple interest amounts to Rs. 9,600 in 2 years and to Rs. 12,000 in 5 years. Find the sum.$q$,array[$q$Rs. 7,500$q$,$q$Rs. 8,000$q$,$q$Rs. 8,400$q$,$q$Rs. 9,000$q$],2,$q$Annual SI = (12000−9600)/3 = 800; SI in 2 yr = 1600; P = 9600−1600 = Rs. 8,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$If the rate of interest on a sum had been 2% higher, it would have fetched Rs. 180 more in 3 years. Find the sum.$q$,array[$q$Rs. 2,500$q$,$q$Rs. 3,000$q$,$q$Rs. 3,600$q$,$q$Rs. 4,000$q$],2,$q$180 = P×2×3/100 → P = Rs. 3,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A sum of Rs. 2,600 is lent in two parts, one at 10% and the other at 12% per annum simple interest. If the total interest for 1 year is Rs. 280, find the part lent at 12%.$q$,array[$q$Rs. 800$q$,$q$Rs. 1,000$q$,$q$Rs. 1,600$q$,$q$Rs. 1,200$q$],2,$q$0.10x+0.12(2600−x)=280 → x=1600 at 10%; part at 12% = Rs. 1,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A sum lent for 3 years at simple interest earns Rs. 630 more when the rate is 3.5% higher. Find the sum.$q$,array[$q$Rs. 5,000$q$,$q$Rs. 6,000$q$,$q$Rs. 7,000$q$,$q$Rs. 6,500$q$],2,$q$630 = P×3.5×3/100 → P = Rs. 6,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$The simple interest on a certain sum for 3 years at 8% per annum equals the simple interest on Rs. 6,000 for 4 years at 5% per annum. Find the sum.$q$,array[$q$Rs. 4,500$q$,$q$Rs. 5,000$q$,$q$Rs. 5,500$q$,$q$Rs. 6,000$q$],2,$q$RHS = 6000×5×4/100 = 1200; P×8×3/100 = 1200 → P = Rs. 5,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A sum at simple interest amounts to Rs. 6,900 in 3 years and to Rs. 7,500 in 5 years. Find the rate percent per annum.$q$,array[$q$4%$q$,$q$5%$q$,$q$6%$q$,$q$8%$q$],2,$q$Annual SI = (7500−6900)/2 = 300; P = 6900−900 = 6000; R = 300×100/6000 = 5%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$Find the difference between the simple interest on Rs. 5,000 at 8% for 3 years and that on Rs. 4,000 at 10% for 2 years.$q$,array[$q$Rs. 300$q$,$q$Rs. 400$q$,$q$Rs. 500$q$,$q$Rs. 600$q$],2,$q$SI1 = 5000×8×3/100 = 1200; SI2 = 4000×10×2/100 = 800; Diff = Rs. 400.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A sum of Rs. 13,000 is divided into two parts such that the simple interest on the first part at 5% per annum equals that on the second part at 8% per annum, both for 1 year. Find the two parts.$q$,array[$q$Rs. 7,000 and Rs. 6,000$q$,$q$Rs. 8,000 and Rs. 5,000$q$,$q$Rs. 9,000 and Rs. 4,000$q$,$q$Rs. 6,500 and Rs. 6,500$q$],2,$q$5·P1 = 8·P2 → P1:P2 = 8:5; parts = 13000×8/13 and 13000×5/13 = Rs. 8,000 and Rs. 5,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A sum of money becomes three times itself in 12 years at simple interest. In how many years will it become five times itself at the same rate?$q$,array[$q$20 years$q$,$q$22 years$q$,$q$24 years$q$,$q$30 years$q$],3,$q$SI = 2P in 12 yr → per yr P/6. Five times needs SI = 4P → T = 4P÷(P/6) = 24 years.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'hard',$q$A person borrows Rs. 5,000 and lends it at a rate 3% higher, gaining Rs. 450 in 3 years. What was the borrowing rate if his lending rate is 12%?$q$,array[$q$8%$q$,$q$9%$q$,$q$10%$q$,$q$11%$q$],2,$q$Gain = 5000×3×3/100 = 450, so rate difference is 3%; lending 12% → borrowing = 12−3 = 9%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$A sum of Rs. 2,700 is divided into two parts such that the simple interest on the first at 3% for 4 years equals the interest on the second at 5% for 3 years. Find the first part.$q$,array[$q$Rs. 1,200$q$,$q$Rs. 1,350$q$,$q$Rs. 1,500$q$,$q$Rs. 1,600$q$],3,$q$0.12·A = 0.15·B → A:B = 5:4; A = 2700×5/9 = Rs. 1,500.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$Rs. 10,000 is lent at 5% for the first 2 years, then at 8% for the next 3 years (simple interest). Find the total interest after 5 years.$q$,array[$q$Rs. 3,000$q$,$q$Rs. 3,400$q$,$q$Rs. 3,800$q$,$q$Rs. 4,000$q$],2,$q$SI = 10000×5×2/100 + 10000×8×3/100 = 1000 + 2400 = Rs. 3,400.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$The simple interest on a sum is 25% of the principal over 5 years. Find the annual rate of interest.$q$,array[$q$4%$q$,$q$5%$q$,$q$6%$q$,$q$8%$q$],2,$q$R×5 = 25 → R = 5% per annum.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$A sum yields simple interest equal to 9/25 of itself. If the number of years equals the rate percent per annum, find the rate.$q$,array[$q$5%$q$,$q$6%$q$,$q$7%$q$,$q$8%$q$],2,$q$R×T = (9/25)×100 = 36 and R = T → R² = 36 → R = 6%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$Rs. 12,000 is lent at simple interest — 5% for the first 3 years, 6% for the next 2 years, and 7% for the sixth year. Find the total interest after 6 years.$q$,array[$q$Rs. 3,840$q$,$q$Rs. 4,080$q$,$q$Rs. 4,320$q$,$q$Rs. 4,500$q$],2,$q$SI = 12000×5×3/100 + 12000×6×2/100 + 12000×7×1/100 = 1800+1440+840 = Rs. 4,080.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$Rs. 12,000 is lent in two parts at 8% and 12% per annum. If the total simple interest for 1 year is Rs. 1,240, find the part lent at 8%.$q$,array[$q$Rs. 4,000$q$,$q$Rs. 5,000$q$,$q$Rs. 6,000$q$,$q$Rs. 7,000$q$],2,$q$0.08x+0.12(12000−x)=1240 → −0.04x=−200 → x = Rs. 5,000 at 8%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$A sum earns simple interest equal to 16/25 of itself, the time being equal to the rate percent per annum. Find the rate.$q$,array[$q$6%$q$,$q$7%$q$,$q$8%$q$,$q$9%$q$],3,$q$R×T = (16/25)×100 = 64 and R = T → R² = 64 → R = 8%.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$A lends a sum to B at 8% and B lends the same to C at 12.5% per annum simple interest. If B gains Rs. 675 in 3 years, find the sum.$q$,array[$q$Rs. 4,500$q$,$q$Rs. 5,000$q$,$q$Rs. 5,500$q$,$q$Rs. 6,000$q$],2,$q$Gain = P×(12.5−8)×3/100 = 675 → P = 675×100/(4.5×3) = Rs. 5,000.$q$);
select public._seed_arith_q($q$Simple Interest$q$,'very_hard',$q$A sum doubles itself in 5 years at simple interest. In how many years will it become four times itself at the same rate?$q$,array[$q$12 years$q$,$q$15 years$q$,$q$18 years$q$,$q$20 years$q$],2,$q$Doubles in 5 yr → R = 20%. Four times needs SI = 3P → T = 300/20 = 15 years.$q$);

drop function public._seed_arith_q(text,text,text,text[],int,text);
